package cat.udl.eps.softarch.demo.domain;

import cat.udl.eps.softarch.demo.domain.Entity.UriEntity;
import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import lombok.AccessLevel;
import lombok.Data;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.Setter;
import lombok.ToString;
import org.hibernate.validator.constraints.Length;

import java.time.Instant;

/**
 * A message for one user, generated by the event handlers (never by clients).
 * The only thing a client may change is the {@code read} flag of its own notifications.
 */
@Entity
@Data
@EqualsAndHashCode(callSuper = true)
public class Notification extends UriEntity<Long> {

    public static final int MAX_TEXT_LENGTH = 255;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @NotNull
    @ManyToOne(optional = false)
    private User recipient;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private NotificationType type;

    @NotBlank
    @Length(max = MAX_TEXT_LENGTH)
    @Column(nullable = false)
    private String message;

    /** URI of the entity the notification is about, e.g. "/meetups/3" (see UriEntity#getUri). */
    @NotBlank
    @Length(max = MAX_TEXT_LENGTH)
    @Column(nullable = false)
    private String targetUri;

    @Column(name = "is_read", nullable = false)
    private boolean read = false;

    @NotNull
    @Column(nullable = false)
    private Instant created;

    /** State as loaded from the database, used by NotificationEventHandler to reject tampering. */
    @Transient
    @JsonIgnore
    @Getter(AccessLevel.NONE)
    @Setter(AccessLevel.NONE)
    @ToString.Exclude
    @EqualsAndHashCode.Exclude
    private LoadedState loadedState;

    public record LoadedState(String recipientId, NotificationType type, String message,
                              String targetUri, Instant created) {}

    @PostLoad
    void captureLoadedState() {
        loadedState = new LoadedState(recipient == null ? null : recipient.getId(),
            type, message, targetUri, created);
    }

    /** @return the persisted state, or null if this instance was not loaded from the database. */
    public LoadedState loadedState() {
        return loadedState;
    }
}
